// The README is the npm landing page (plan §8.3, D1, D39; docs-09, research-10). Its install
// string, quick starts and no-build snippet are generated by scripts/sync-readme.mjs from
// packages/snaplot/package.json and src/examples/start/first-chart.*, so they always run: the
// smoke spec executes the same files on the "Your first chart" page.
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';

const site = fileURLToPath(new URL('..', import.meta.url));
const repo = join(site, '..');
const readme = () => readFileSync(join(repo, 'README.md'), 'utf8');
const pkg = JSON.parse(readFileSync(join(repo, 'packages/snaplot/package.json'), 'utf8')) as {
  version: string;
  description: string;
  keywords: string[];
};
const example = (suffix: string) =>
  readFileSync(join(site, `src/examples/start/first-chart${suffix}`), 'utf8').trimEnd();

/** The text between `<!-- sync-readme:<name> -->` and `<!-- /sync-readme:<name> -->`. */
function block(text: string, name: string): string | undefined {
  const m = new RegExp(
    `<!-- sync-readme:${name} -->\\n([\\s\\S]*?)\\n<!-- /sync-readme:${name} -->`,
  ).exec(text);
  return m?.[1];
}

/** The body of the one fenced code block in `text`. */
const fenced = (text = '') => /```[a-z]*\n([\s\S]*?)\n```/.exec(text)?.[1];

describe('README.md', () => {
  it.fails('[docs-09] matches what sync-readme generates (sync-readme --check)', () => {
    const run = spawnSync(process.execPath, [join(repo, 'scripts/sync-readme.mjs'), '--check'], {
      encoding: 'utf8',
    });
    expect(run.stderr + run.stdout).toMatch(/up to date/);
    expect(run.status).toBe(0);
  });

  it.fails('[docs-09] shows the install string and three quick starts that the docs run', () => {
    const text = readme();
    const install = pkg.version.includes('-') ? 'npm i snaplot@next' : 'npm i snaplot';
    expect(fenced(block(text, 'install'))).toBe(install);
    expect(fenced(block(text, 'vanilla'))).toBe(example('.ts'));
    expect(fenced(block(text, 'react'))).toBe(example('.react.tsx'));
    expect(fenced(block(text, 'solid'))).toBe(example('.solid.tsx'));
    const noBuild = fenced(block(text, 'no-build')) ?? '';
    expect(noBuild).toContain('<script type="module">');
    expect(noBuild).toContain(`https://cdn.jsdelivr.net/npm/snaplot@${pkg.version}/+esm`);
  });

  it.fails('[docs-09] works on npm: absolute links, no working notes, a browser floor and non-goals', () => {
    const text = readme();
    const links = [...text.matchAll(/\]\(([^)]+)\)/g)].map((m) => m[1] ?? '');
    expect(links.length).toBeGreaterThan(3);
    expect(links.filter((link) => !/^https:\/\//.test(link))).toEqual([]);
    expect(text).not.toMatch(/overhaul|working tree|working-tree|dev:lab|chart-lab/i);
    expect(text).toMatch(/^## Browser support$/m);
    expect(text).toMatch(/Safari 16\.4/);
    expect(text).toMatch(/^## Not yet supported$/m);
  });

  it.fails('[research-10] opens with the package description: one framework-neutral sentence', () => {
    expect(pkg.description).toBe(
      'Canvas charts for live data. One options object for vanilla JS, React and Solid.',
    );
    const lede = readme()
      .split('\n')
      .find((line) => line.trim() && !line.startsWith('#'));
    expect(lede).toBe(pkg.description);
    expect(pkg.keywords).toEqual(expect.arrayContaining(['react', 'solid', 'canvas', 'chart']));
  });
});
